CREATE OR ALTER PROCEDURE [dbo].[uspVehicle_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @VehicleType NVARCHAR(MAX) = NULL
	, @Status NVARCHAR(MAX) = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[Code]
			, t.[LicensePlate]
			, t.[VehicleType]
			, t.[Capacity]
			, t.[Status]
			, t.[Note]
			, t.[DefaultDriverEmployeeId] -- GAP-LOG-DRV (D-128)
			, t.[CreatedDate]
		FROM [dbo].[Vehicle] AS t
		
		-- MA-1 (D-63): mã xe XE-NNNNN do máy chủ sinh → tìm được cả theo biển số.
		WHERE (ISNULL(@SearchText, '') = '' OR t.[Code] LIKE CONCAT('%', @SearchText, '%') OR t.[LicensePlate] LIKE CONCAT('%', @SearchText, '%'))
			AND (ISNULL(@VehicleType, '') = '' OR t.[VehicleType] = @VehicleType)
			AND (ISNULL(@Status, '') = '' OR t.[Status] = @Status)
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'code' THEN r.[Code] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'code' THEN r.[Code] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'licensePlate' THEN r.[LicensePlate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'licensePlate' THEN r.[LicensePlate] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'vehicleType' THEN r.[VehicleType] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'vehicleType' THEN r.[VehicleType] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'capacity' THEN r.[Capacity] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'capacity' THEN r.[Capacity] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'status' THEN r.[Status] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'status' THEN r.[Status] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'note' THEN r.[Note] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'note' THEN r.[Note] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
GO
